sdl:
directive @cost(weight: String!) on ARGUMENT_DEFINITION | ENUM | FIELD_DEFINITION | INPUT_FIELD_DEFINITION | OBJECT | SCALAR
directive @listSize(
  assumedSize: Int
  slicingArguments: [String!]
  sizedFields: [String!]
  requireOneSlicingArgument: Boolean = true
) on FIELD_DEFINITION
type Edge { node: String }
type Connection { edges: [Edge] }
type Query {
  items(first: Int): Connection @listSize(
    slicingArguments: ["first"]
    sizedFields: ["edges"]
  )
}
